// SCRIPT - AI OLLAMA (chạy local): bị TAG hoặc bị REPLY thì nói chuyện bình thường, không giới hạn độ dài, được chửi bậy.
// BƯỚC 1: điền ID bot vào BOT_ID bên dưới VÀ thay ID_BOT trong ô "Lệnh kích hoạt". Regex: <@!?ID_BOT>|^!ai\b
//   -> Muốn nhận cả REPLY: đổi ô kích hoạt thành [\s\S]+ (Regex) và để script này ở CUỐI danh sách.
// BƯỚC 2: cài Ollama và chạy: ollama pull qwen2.5:7b
// QUAN TRỌNG: tăng "Giới hạn chạy (ms)" của script lên 60000.
// Lệnh: !ai on | !ai off | !ai model <tên> | !ai clear | !ai (xem trạng thái). Bật/tắt/đổi model chỉ Admin / chủ server.
const BOT_ID = '1554109376246317117';
const OLLAMA_URL = 'http://127.0.0.1:11434/api/chat';
const DEFAULT_MODEL = 'hf.co/QuantFactory/Qwen2.5-7B-Instruct-Uncensored-GGUF:Q4_K_M';
const MEMORY_TURNS = 6;
const HTTP_TIMEOUT = 13000;  // phải nhỏ hơn giới hạn chạy 15000
const MAX_TOKENS = 800;      // ngắn lại để sinh kịp
const MAX_CHARS = 1900;      // Discord chỉ cho tối đa 2000 ký tự/tin nhắn

const SYSTEM_PROMPT = [
  'chat bot thông minh'
].join('\n');

const isStaff = ctx.user.isAdmin || ctx.user.isOwner;
const text = String(ctx.content || '').trim();
const model = store.model || DEFAULT_MODEL;

// ---- Lệnh điều khiển ----
const cmd = text.match(/^!ai(?:\s+(\S+))?(?:\s+(.+))?$/i);
if (cmd) {
  const sub = (cmd[1] || '').toLowerCase(), arg = (cmd[2] || '').trim();
  if (['on', 'bat', 'bật', 'off', 'tat', 'tắt', 'model', 'clear'].includes(sub) && !isStaff) return 'Chỉ Admin / chủ server mới dùng được.';
  if (['on', 'bat', 'bật'].includes(sub)) { store.enabled = true; return '✅ AI đã **BẬT**. Tag hoặc reply bot để nói chuyện.'; }
  if (['off', 'tat', 'tắt'].includes(sub)) { store.enabled = false; return '⛔ AI đã **TẮT**.'; }
  if (sub === 'model') { if (!arg) return 'Model hiện tại: `' + model + '`'; store.model = arg; return 'Đã đổi model sang `' + arg + '`'; }
  if (sub === 'clear') { store.hist = {}; return '🧹 Đã xóa trí nhớ.'; }
  return 'AI đang **' + (store.enabled === false ? 'TẮT' : 'BẬT') + '** | model: `' + model + '`';
}

// ---- Chỉ trả lời khi bị tag / reply ----
if (!/^\d{15,25}$/.test(BOT_ID)) { print('Chưa điền BOT_ID ở đầu script.'); return; }
const tagged = text.includes('<@' + BOT_ID + '>') || text.includes('<@!' + BOT_ID + '>') || (ctx.mentions || []).some(m => m.id === BOT_ID);
if (!tagged) return;
if (store.enabled === false) return;

// ---- Chuẩn bị nội dung ----
let q = text.replace(/<@!?\d{15,25}>/g, ' ').replace(/\s+/g, ' ').trim();
if (!q) q = '(chỉ gọi tên, không nói gì)';
const userLine = ctx.user.display + ': ' + q.slice(0, 1500);
store.hist = store.hist || {};
const hist = store.hist[ctx.channelId] = store.hist[ctx.channelId] || [];
const messages = [{ role: 'system', content: SYSTEM_PROMPT }, ...hist, { role: 'user', content: userLine }];

// ---- Gọi Ollama ----
const ac = new AbortController();
const timer = setTimeout(() => ac.abort(), HTTP_TIMEOUT);
let out = '';
try {
  const res = await fetch(OLLAMA_URL, {
    method: 'POST', headers: { 'Content-Type': 'application/json' }, signal: ac.signal,
    body: JSON.stringify({ model, messages, stream: false, think: false, keep_alive: '30m', options: { temperature: 0.85, top_p: 0.92, num_predict: MAX_TOKENS } })
  });
  if (!res.ok) throw new Error('Ollama trả về HTTP ' + res.status + ' - ' + (await res.text()).slice(0, 200));
  out = String(((await res.json()).message || {}).content || '');
} catch (e) {
  throw new Error(e.name === 'AbortError'
    ? 'Ollama quá chậm (>' + HTTP_TIMEOUT + 'ms): model đang nạp? thử lại hoặc dùng model nhỏ hơn'
    : 'Không gọi được Ollama (' + OLLAMA_URL + '): ' + e.message + ' - đã chạy ollama và "ollama pull ' + model + '" chưa?');
} finally { clearTimeout(timer); }

// ---- Làm sạch (giữ nguyên xuống dòng, code block, độ dài) ----
out = out.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
out = out.replace(/^["“”‘’`]+|["“”‘’`]+$/g, '').replace(/^(mày|bot|ai)\s*[:：]\s*/i, '').trim();
out = out.slice(0, MAX_CHARS);
if (!out) out = 'cút';

// ---- Lưu trí nhớ ----
hist.push({ role: 'user', content: userLine }, { role: 'assistant', content: out });
while (hist.length > MEMORY_TURNS * 2) hist.shift();
return out;

// SCRIPT - CLONE EMOJI / STICKER: ai gửi emoji (của server khác) hoặc sticker -> bot kiểm tra server mình có chưa, chưa có thì tải về rồi thêm vào server.
// Lệnh kích hoạt (regex): <a?:\w{2,32}:\d{15,25}>|^\s*$      (^\s*$ = tin chỉ có sticker/ảnh, không có chữ)
// Bot cần quyền "Manage Guild Expressions" (Quản lý emoji & sticker). Script gọi thẳng Discord API nên CẦN token (xem 2 dòng TOKEN / ENV_FILE bên dưới).
const fs = require('fs');
const API = 'https://discord.com/api/v10';
const CDN = 'https://cdn.discordapp.com';
const MEDIA = 'https://media.discordapp.net';
const TOKEN = '';      // CÁCH 1: dán token bot vào đây. KHÔNG nên: data.json bị đồng bộ lên git -> lộ token.
const ENV_FILE = '';   // CÁCH 2 (nên dùng): đường dẫn file .env của bot, vd '/home/user/botcuadat-main/.env' hoặc 'C:/bot/.env'. Script đọc DISCORD_TOKEN trong đó.
const MAX_EMOJI = 5;        // tối đa số emoji clone từ 1 tin nhắn
const CLONE_STICKER = true; // true = clone cả sticker
const SAY_EXISTS = false;   // true = báo cả khi server đã có sẵn

if (!ctx.guildId) return;
const text = String(ctx.content || '');
const emojis = [], seen = new Set();
for (const m of text.matchAll(/<(a?):(\w{2,32}):(\d{15,25})>/g)) {
  if (seen.has(m[3])) continue; seen.add(m[3]);
  emojis.push({ animated: !!m[1], name: m[2], id: m[3] });
}
const blank = !text.trim();                       // tin không chữ: có thể là sticker
if (!emojis.length && !(blank && CLONE_STICKER)) return;

let token = TOKEN;
if (!token && ENV_FILE) {
  try { const m = fs.readFileSync(ENV_FILE, 'utf8').match(/^\s*DISCORD_TOKEN\s*=\s*(.+?)\s*$/m); if (m) token = m[1].replace(/^["']|["']$/g, ''); }
  catch (e) { print('Không đọc được ENV_FILE: ' + e.message); }
}
if (!token) {
  print('Chưa có token: điền TOKEN hoặc ENV_FILE ở đầu script.');
  if (emojis.length) reply('❌ Script clone chưa có token bot (điền TOKEN hoặc ENV_FILE ở đầu script).');
  return;
}

const UA = { 'User-Agent': 'DiscordBot (botcuadat, 1.0)' };
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function dc(method, path, body, form) {
  for (let t = 0; t < 2; t++) {
    const opt = { method, headers: { ...UA, Authorization: 'Bot ' + token } };
    if (body) { opt.headers['Content-Type'] = 'application/json'; opt.body = JSON.stringify(body); }
    if (form) opt.body = form;
    const r = await fetch(API + path, opt);
    const raw = await r.text(); let j; try { j = JSON.parse(raw); } catch { j = raw; }
    if (r.status === 429 && t === 0) { await sleep(Math.min(((j && j.retry_after) || 1) * 1000, 4000)); continue; }
    if (!r.ok) throw new Error((j && j.message ? j.message : 'HTTP ' + r.status) + (r.status === 403 ? ' (bot thiếu quyền Manage Guild Expressions?)' : ''));
    return j;
  }
}
async function img(url) {
  const r = await fetch(url, { headers: UA });
  if (!r.ok) throw new Error('Tải ảnh lỗi ' + r.status);
  return Buffer.from(await r.arrayBuffer());
}

const added = [], exists = [], errors = [];
try {
  // ---------- EMOJI ----------
  if (emojis.length) {
    const have = await dc('GET', '/guilds/' + ctx.guildId + '/emojis');
    const haveId = new Set(have.map(e => e.id)), haveName = new Set(have.map(e => e.name.toLowerCase()));
    for (const e of emojis.slice(0, MAX_EMOJI)) {
      if (haveId.has(e.id) || haveName.has(e.name.toLowerCase())) { exists.push(e.name); continue; }
      try {
        const url = CDN + '/emojis/' + e.id + (e.animated ? '.gif' : '.png') + '?size=128';
        let buf = await img(url);
        if (buf.length > 256 * 1024) buf = await img(url.replace('size=128', 'size=64'));
        if (buf.length > 256 * 1024) throw new Error('ảnh emoji quá 256KB');
        const c = await dc('POST', '/guilds/' + ctx.guildId + '/emojis', { name: e.name, image: 'data:' + (e.animated ? 'image/gif' : 'image/png') + ';base64,' + buf.toString('base64') });
        haveName.add(e.name.toLowerCase());
        added.push('<' + (c.animated ? 'a' : '') + ':' + c.name + ':' + c.id + '>');
      } catch (err) { errors.push('emoji `' + e.name + '`: ' + err.message); }
    }
    if (emojis.length > MAX_EMOJI) errors.push('chỉ clone ' + MAX_EMOJI + ' emoji đầu tiên');
  }

  // ---------- STICKER ----------
  if (CLONE_STICKER && blank) {
    const m = await dc('GET', '/channels/' + ctx.channelId + '/messages/' + ctx.messageId);
    const st = (m.sticker_items || [])[0];
    if (st) {
      const list = await dc('GET', '/guilds/' + ctx.guildId + '/stickers');
      if (list.some(s => s.id === st.id || s.name.toLowerCase() === st.name.toLowerCase())) exists.push(st.name);
      else if (st.format_type === 3) errors.push('sticker `' + st.name + '` dạng Lottie, bot không upload được');
      else {
        try {
          const info = await dc('GET', '/stickers/' + st.id).catch(() => ({}));
          const gif = st.format_type === 4;
          const buf = await img(gif ? MEDIA + '/stickers/' + st.id + '.gif' : CDN + '/stickers/' + st.id + '.png?size=320');
          if (buf.length > 512 * 1024) throw new Error('ảnh sticker quá 512KB');
          const fd = new FormData();
          fd.append('name', (st.name.length < 2 ? st.name + '__' : st.name).slice(0, 30));
          fd.append('tags', String(info.tags || st.name).slice(0, 200).padEnd(2, '_'));
          fd.append('description', String(info.description || '').slice(0, 100));
          fd.append('file', new Blob([buf], { type: gif ? 'image/gif' : 'image/png' }), 'sticker.' + (gif ? 'gif' : 'png'));
          const c = await dc('POST', '/guilds/' + ctx.guildId + '/stickers', null, fd);
          added.push('sticker **' + c.name + '**');
        } catch (err) { errors.push('sticker `' + st.name + '`: ' + err.message); }
      }
    }
  }
} catch (e) { errors.push(e.message); }

const out = [];
if (added.length) out.push('✅ Đã thêm vào server: ' + added.join(' '));
if (SAY_EXISTS && exists.length) out.push('ℹ️ Server đã có: ' + exists.join(', '));
if (errors.length) out.push('❌ ' + errors.join(' | '));
print('thêm ' + added.length + ', đã có ' + exists.length + ', lỗi ' + errors.length);
if (out.length) reply(out.join('\n'));

// SCRIPT - OẢN TÙ TÌ v2 (embed đẹp): đấu Bot hoặc đấu người, 3 round, có BXH.
// 1 BẢNG CHUNG cho cả phòng: ai cũng thấy tỉ số, ai đã chọn / chưa chọn, kết quả từng round.
// Bấm ✊ ✌️ ✋ ngay trên bảng -> lựa chọn của bạn CHỈ MÌNH BẠN thấy (tin ẩn), đến khi lật bài mới công khai.
// Cần bản bot đã vá (index.js + scriptRunner.js bản mới, có hỗ trợ embed).
// Cài đặt: Lệnh kích hoạt = ^!(oantuti|ott|rps)(\s|$) | Kiểu: Regex | Gửi vào kênh | Giới hạn chạy 8000
// Lệnh:  !oantuti | !oantuti @đối_thủ | !oantuti top | !oantuti huy

const ROUNDS = 3;          // số round mỗi trận
const PICK_SEC = 15;       // thời gian chọn mỗi round (giây)
const REVEAL_SEC = 4;      // thời gian hiện kết quả round trước khi sang round mới (giây)
const INVITE_SEC = 60;     // thời gian chờ chấp nhận / chọn chế độ (giây)
const COUNT_BOT = true;    // true = trận đấu với Bot cũng tính vào BXH
const TOP_N = 10;          // số người hiện trong BXH

const ME = (ctx.user && ctx.user.id) || '';
const now = ctx.now || Date.now();
const NOW = () => ctx.now || Date.now();
store.sess = store.sess || {};
store.by = store.by || {};
store.stats = store.stats || {};

const MV = { k: { n: 'Kéo', e: '✌️' }, b: { n: 'Búa', e: '✊' }, g: { n: 'Bao', e: '✋' } };
const BEATS = { k: 'g', b: 'k', g: 'b' };
const mv = c => MV[c].e + ' **' + MV[c].n + '**';
const U = id => id === 'bot' ? '🤖 **Bot**' : '<@' + id + '>';
const rnd = () => ['k', 'b', 'g'][Math.floor(Math.random() * 3)];
const rid = () => Math.random().toString(36).slice(2, 8);
const ts = sec => Math.floor((now + sec * 1000) / 1000);
const COL = { blue: 0x5865F2, red: 0xED4245, green: 0x57F287, yellow: 0xFEE75C, gold: 0xF1C40F, grey: 0x95A5A6 };
const ICON = { a: '🟦', b: '🟥' };
const RULE = '✊ Búa **thắng** ✌️ Kéo  ·  ✌️ Kéo **thắng** ✋ Bao  ·  ✋ Bao **thắng** ✊ Búa';

// ---------- phiên ----------
function drop(s) { delete store.sess[s.id]; for (const u of [s.a, s.b]) if (store.by[u] === s.id) delete store.by[u]; }
for (const s of Object.values(store.sess)) if (s.exp < now) drop(s);
const mine = id => store.sess[store.by[id]] || null;
const sideOf = (s, id) => s.a === id ? 'a' : (s.b === id ? 'b' : null);
const newSess = (a, b, st, secs) => ({ id: rid(), a, b, st, exp: now + (secs + 20) * 1000, round: 0, sc: [0, 0], pk: {}, h: [] });

// ---------- BXH ----------
const stat = id => (store.stats[id] = store.stats[id] || { w: 0, l: 0, d: 0 });
function boardEmbed() {
  const rows = Object.entries(store.stats).map(([id, s]) => ({ id, ...s, t: s.w + s.l + s.d })).filter(x => x.t > 0)
    .sort((x, y) => y.w - x.w || (y.w / y.t) - (x.w / x.t) || x.l - y.l).slice(0, TOP_N);
  if (!rows.length) return { title: '🏆 BẢNG XẾP HẠNG OẢN TÙ TÌ', description: 'Chưa có ai chơi.\nGõ `!oantuti` để bắt đầu trận đầu tiên!', color: COL.gold };
  const medal = ['🥇', '🥈', '🥉'];
  return {
    title: '🏆 BẢNG XẾP HẠNG OẢN TÙ TÌ', color: COL.gold,
    description: rows.map((r, i) => (medal[i] || '`#' + (i + 1) + '`') + ' <@' + r.id + '>\n┗ ✅ **' + r.w + '** thắng · ❌ **' + r.l + '** thua · 🤝 **' + r.d + '** hòa · 📈 **' + Math.round(100 * r.w / r.t) + '%**').join('\n\n'),
    footer: 'Xếp theo số trận thắng, rồi đến tỉ lệ thắng'
  };
}

// ---------- giao diện (embed) ----------
const bar = s => s.h.map(x => x.r === 'a' ? ICON.a : x.r === 'b' ? ICON.b : '⬜').concat(Array(Math.max(0, ROUNDS - s.h.length)).fill('⬛')).join(' ');
const histText = s => s.h.map((x, i) => '`R' + (i + 1) + '` ' + (x.pa ? MV[x.pa].e : '⏰') + ' ⚔️ ' + (x.pb ? MV[x.pb].e : '⏰') + '  →  ' +
  (x.r === 'd' ? '🤝 Hòa' : '🏅 ' + U(x.r === 'a' ? s.a : s.b))).join('\n');
const scoreFields = (s, la, lb, mid) => [
  { name: ICON.a + ' Người chơi 1', value: U(s.a) + '\n' + la, inline: true },
  { name: '📊 Tỉ số', value: '# ' + s.sc[0] + ' : ' + s.sc[1] + (mid ? '\n' + mid : ''), inline: true },
  { name: ICON.b + ' Người chơi 2', value: U(s.b) + '\n' + lb, inline: true }
];

function menuView(s) {
  return {
    content: '', mentions: [],
    embeds: [{
      title: '✊  ✌️  ✋   OẢN TÙ TÌ', color: COL.blue,
      description: ctx.user.mention + ', chọn chế độ chơi nhé!\n⏱️ Menu hết hạn <t:' + ts(INVITE_SEC) + ':R>',
      fields: [
        { name: '🎯 Thể thức', value: '**' + ROUNDS + '** round · mỗi round **' + PICK_SEC + 's** để chọn', inline: true },
        { name: '🤖 Đấu Bot', value: 'Bấm nút xanh để vào trận ngay', inline: true },
        { name: '👥 Đấu người', value: 'Gõ `!oantuti @đối_thủ`', inline: true },
        { name: '📜 Luật chơi', value: RULE }
      ],
      footer: '🔒 Lựa chọn của bạn luôn được giữ bí mật cho đến khi lật bài'
    }],
    buttons: [[
      { label: '🤖  Đấu với Bot', id: 'bot:' + s.id, style: 'success' },
      { label: '👥  Đấu với người', id: 'pvp:' + s.id, style: 'primary' },
      { label: '🏆  BXH', id: 'top', style: 'secondary', ephemeral: true },
      { label: '✖', id: 'x:' + s.id, style: 'danger' }
    ]]
  };
}

function inviteView(s) {
  return {
    content: '<@' + s.b + '>', mentions: [s.b],
    embeds: [{
      title: '⚔️  LỜI THÁCH ĐẤU OẢN TÙ TÌ', color: COL.red,
      description: U(s.a) + ' thách đấu ' + U(s.b) + '!\n\n⏱️ Trả lời trước <t:' + ts(INVITE_SEC) + ':R>',
      fields: [
        { name: '🎯 Thể thức', value: '**' + ROUNDS + '** round · **' + PICK_SEC + 's** mỗi round', inline: true },
        { name: '📜 Luật chơi', value: RULE }
      ]
    }],
    buttons: [[
      { label: '✅  Chấp nhận', id: 'acc:' + s.id, style: 'success' },
      { label: '❌  Từ chối', id: 'dec:' + s.id, style: 'danger' }
    ]]
  };
}

function roundView(s) {
  const st = x => s[x] === 'bot' ? '🤖 Sẵn sàng' : (s.pk[x] ? '✅ **Đã chọn**' : '⏳ Đang chọn...');
  const f = scoreFields(s, st('a'), st('b'), bar(s));
  if (s.h.length) f.push({ name: '📜 Kết quả các round', value: histText(s) });
  return {
    content: '', mentions: [],
    embeds: [{
      title: '✊  ✌️  ✋   ROUND ' + s.round + ' / ' + ROUNDS, color: COL.blue,
      description: '🎯 **Chọn nước đi của bạn bên dưới!**\n⏱️ Hết giờ <t:' + ts(PICK_SEC) + ':R>',
      fields: f,
      footer: '🔒 Bấm nút là xong — lựa chọn chỉ mình bạn thấy, đến khi lật bài mới công khai'
    }],
    buttons: [[
      { label: '✊   BÚA', id: 'mv:' + s.id + ':' + s.round + ':b', style: 'danger', ephemeral: true },
      { label: '✌️   KÉO', id: 'mv:' + s.id + ':' + s.round + ':k', style: 'primary', ephemeral: true },
      { label: '✋   BAO', id: 'mv:' + s.id + ':' + s.round + ':g', style: 'success', ephemeral: true }
    ]]
  };
}

function revealView(s) {
  const x = s.h[s.h.length - 1];
  const head = x.r === 'd' ? '🤝 **Hòa round này!**' : '🏅 ' + U(x.r === 'a' ? s.a : s.b) + ' **thắng round ' + s.round + '!**';
  const pick = p => p ? MV[p].e + ' **' + MV[p].n + '**' : '⏰ Không chọn';
  return {
    content: '', mentions: [], buttons: [],
    embeds: [{
      title: '🎬  LẬT BÀI — ROUND ' + s.round + ' / ' + ROUNDS,
      color: x.r === 'a' ? COL.blue : x.r === 'b' ? COL.red : COL.yellow,
      description: head,
      fields: scoreFields(s, pick(x.pa), pick(x.pb), bar(s)).concat([{ name: '📜 Kết quả các round', value: histText(s) }]),
      footer: '⏭️ Round ' + (s.round + 1) + ' sắp bắt đầu...'
    }]
  };
}

function finalView(s) {
  const [x, y] = s.sc, w = x > y ? 'a' : (y > x ? 'b' : 'd');
  const tag = side => w === 'd' ? '🤝 Hòa' : (w === side ? '👑 Chiến thắng' : '💔 Thua');
  return {
    content: '', mentions: [],
    embeds: [{
      title: '🏁  KẾT THÚC TRẬN OẢN TÙ TÌ', color: w === 'a' ? COL.blue : w === 'b' ? COL.red : COL.gold,
      description: w === 'd' ? '🤝 **HÒA CHUNG CUỘC!**' : '🏆 ' + U(w === 'a' ? s.a : s.b) + ' **THẮNG CHUNG CUỘC!** 🎉',
      fields: scoreFields(s, tag('a'), tag('b'), bar(s)).concat([{ name: '📜 Diễn biến trận đấu', value: histText(s) || '—' }])
    }],
    buttons: [[{ label: '🏆  BXH', id: 'top', style: 'secondary', ephemeral: true }]
      .concat(s.b === 'bot' ? [{ label: '🔁  Đấu lại', id: 'rm:' + s.a, style: 'primary' }] : [])]
  };
}

const plain = (text, color) => ({ content: '', embeds: [{ description: text, color: color || COL.grey }], buttons: [], mentions: [] });

// ---------- luồng chơi ----------
function show(s, view, upd) { if (upd) ui.update(view, 'm:' + s.id); else ui.edit('m:' + s.id, view); }

function startRound(s, upd) {
  s.round++; s.pk = {}; s.resolving = false; s.st = 'play'; s.exp = NOW() + (PICK_SEC + REVEAL_SEC + 40) * 1000;
  show(s, roundView(s), upd);
  ui.after(PICK_SEC, 'rt:' + s.id + ':' + s.round);
}

function resolve(s) {
  // Chặn resolve bị gọi 2 lần (nút cuối + timer cũ).
  if (!s || s.st !== 'play') return;
  if (s.resolving) return;
  s.resolving = true;
  const pa = s.pk.a;
  if (s.b === 'bot' && !s.pk.b) s.pk.b = rnd();
  const pb = s.pk.b;
  let r;
  if (pa && pb) r = pa === pb ? 'd' : (BEATS[pa] === pb ? 'a' : 'b');
  else if (pa) r = 'a'; else if (pb) r = 'b'; else r = 'd';
  if (r === 'a') s.sc[0]++; else if (r === 'b') s.sc[1]++;
  s.h.push({ pa: pa || '', pb: pb || '', r });
  if (s.round < ROUNDS) {
    s.st = 'reveal'; s.exp = now + (REVEAL_SEC + 40) * 1000;
    show(s, revealView(s));
    ui.after(REVEAL_SEC, 'nx:' + s.id + ':' + s.round);
  } else finish(s);
}

function finish(s) {
  if (!s) return;
  const [x, y] = s.sc, w = x > y ? 'a' : (y > x ? 'b' : 'd');
  const real = id => id !== 'bot';
  if (s.b !== 'bot' || COUNT_BOT) {
    if (w === 'd') { if (real(s.a)) stat(s.a).d++; if (real(s.b)) stat(s.b).d++; }
    else { const win = w === 'a' ? s.a : s.b, lose = w === 'a' ? s.b : s.a; if (real(win)) stat(win).w++; if (real(lose)) stat(lose).l++; }
  }
  show(s, finalView(s));
  drop(s);
}

// ---------- 1) tin nhắn ----------
function onMessage() {
  const arg = (String(ctx.content || '').trim().match(/^!\S+\s*([\s\S]*)$/) || [0, ''])[1].trim();
  const cur = mine(ME);

  if (/^(top|bxh|rank)\b/i.test(arg)) { ui.send({ embeds: [boardEmbed()], mentions: [] }); return; }
  if (/^(huy|hủy|cancel|stop)\b/i.test(arg)) {
    if (!cur) { reply('Bạn không có phiên oản tù tì nào đang chạy.'); return; }
    drop(cur);
    ui.edit('m:' + cur.id, plain('🚫 ' + ctx.user.mention + ' đã hủy phiên oản tù tì.'));
    reply('✅ Đã hủy phiên.'); return;
  }

  if (cur && cur.st === 'menu') { drop(cur); ui.edit('m:' + cur.id, plain('↪️ Menu cũ đã đóng.')); }
  else if (cur) { reply('⚠️ Bạn đang có 1 phiên oản tù tì chưa xong (gõ `!oantuti huy` để hủy).'); return; }

  const opp = (ctx.mentions || []).find(m => m.id !== ME);
  if (opp) {
    if (opp.bot) { reply('🤖 Muốn đấu Bot thì gõ `!oantuti` rồi bấm nút "Đấu với Bot" nhé.'); return; }
    if (mine(opp.id)) { reply('⚠️ ' + opp.mention + ' đang ở trong một phiên oản tù tì khác rồi.'); return; }
    const s = newSess(ME, opp.id, 'invite', INVITE_SEC);
    store.sess[s.id] = s; store.by[ME] = s.id; store.by[opp.id] = s.id;
    ui.send(inviteView(s), 'm:' + s.id);
    ui.after(INVITE_SEC, 'ex:' + s.id);
    return;
  }

  const s = newSess(ME, null, 'menu', INVITE_SEC);
  store.sess[s.id] = s; store.by[ME] = s.id;
  ui.send(menuView(s), 'm:' + s.id);
  ui.after(INVITE_SEC, 'ex:' + s.id);
}

// ---------- 2) bấm nút ----------
function onButton(it) {
  const [act, sid, a1, a2] = String(it && it.customId || '').split(':');
  const clicker = it && it.userId;
  if (!act) return;
  const no = text => ui.reply(plain(text, COL.red));
  if (act === 'top') { ui.reply({ embeds: [boardEmbed()], mentions: [] }); return; }

  if (act === 'rm') {                                  // đấu lại với Bot
    if (clicker !== sid) return no('Nút này chỉ dành cho người vừa chơi.');
    if (mine(clicker)) return no('Bạn đang có một phiên chưa xong rồi.');
    const n = newSess(clicker, 'bot', 'play', PICK_SEC);
    store.sess[n.id] = n; store.by[clicker] = n.id;
    startRound(n, true); return;
  }

  const s = store.sess[sid];
  if (!s) {
    if (it.kind === 'e') ui.reply(plain('⌛ Phiên này đã kết thúc.'));
    else ui.update(plain('⌛ Phiên này đã kết thúc hoặc hết hạn.'));
    return;
  }
  const side = sideOf(s, clicker);

  if (act === 'bot') {
    if (clicker !== s.a || s.st !== 'menu') return no('Menu này không phải của bạn.');
    s.b = 'bot';
    startRound(s, true); return;
  }
  if (act === 'pvp') {
    if (clicker !== s.a || s.st !== 'menu') return no('Menu này không phải của bạn.');
    return ui.reply({ embeds: [{ description: '👥 Để đấu với người, gõ:\n`!oantuti @tên_đối_thủ`\nĐối thủ sẽ nhận lời mời có nút **Chấp nhận / Từ chối**.', color: COL.blue }] });
  }
  if (act === 'x') {
    if (clicker !== s.a) return no('Menu này không phải của bạn.');
    drop(s); ui.update(plain('🚫 ' + U(clicker) + ' đã đóng menu.')); return;
  }
  if (act === 'acc') {
    if (s.st !== 'invite') return no('Lời mời này không còn hiệu lực.');
    if (clicker !== s.b) return no(clicker === s.a ? 'Bạn là người thách đấu, hãy đợi đối thủ trả lời.' : 'Lời mời này không dành cho bạn.');
    startRound(s, true); return;
  }
  if (act === 'dec') {
    if (s.st !== 'invite') return no('Lời mời này không còn hiệu lực.');
    if (!side) return no('Lời mời này không dành cho bạn.');
    drop(s);
    ui.update(plain(clicker === s.b ? '❌ ' + U(s.b) + ' đã từ chối lời thách đấu của ' + U(s.a) + '.' : '🚫 ' + U(s.a) + ' đã hủy lời thách đấu.', COL.red));
    return;
  }
  if (act === 'mv') {                                  // chọn búa / kéo / bao (tin ẩn)
    if (s.st !== 'play' || s.round !== +a1) return ui.reply(plain('⏰ Round này đã kết thúc.'));
    if (s.exp <= NOW()) return ui.reply(plain('⏰ Đã hết thời gian chọn.'));
    if (!side || !MV[a2]) return no('Bạn không tham gia trận này.');
    if (s.pk[side]) return ui.reply(plain('✅ Bạn đã chọn ' + mv(s.pk[side]) + ' rồi, chờ lật bài nhé.', COL.green));
    s.pk[side] = a2;
    ui.reply(plain('✅ Bạn đã chọn ' + mv(a2) + '!' + ((s.b === 'bot' || (s.pk.a && s.pk.b)) ? '' : '\n⏳ Đang chờ đối thủ...') + '\n🔒 Chỉ mình bạn thấy lựa chọn này.', COL.green));
    if (s.b === 'bot' || (s.pk.a && s.pk.b)) resolve(s);
    else ui.edit('m:' + s.id, roundView(s));
    return;
  }
}

// ---------- 3) hẹn giờ ----------
function onTimer(data) {
  const [act, sid, rd] = String(data).split(':');
  const s = store.sess[sid];
  if (!s) return;
  if (act === 'ex' && (s.st === 'menu' || s.st === 'invite')) {
    drop(s);
    ui.edit('m:' + sid, plain(s.st === 'invite' ? '⌛ ' + U(s.b) + ' không trả lời, lời thách đấu đã hết hạn.' : '⌛ Menu đã hết hạn.'));
  } else if (act === 'rt' && s.st === 'play' && s.round === +rd) resolve(s);
  else if (act === 'nx' && s.st === 'reveal' && s.round === +rd) startRound(s, false);
}

