  if (!ok) return '\nTệp: người đang nói chuyện KHÔNG có quyền nhận tệp / ảnh / video từ bạn, tuyệt đối không dùng các thẻ [[IMG]], [[VIDEO]], [[FILE]], [[FILEDATA]], [[GENIMG]].';
  let r = '\nGửi tệp: bạn CÓ THỂ đính kèm tệp vào câu trả lời bằng các thẻ đặt trong câu trả lời (hệ thống tự ẩn thẻ và đính kèm tệp): '
    + '[[FILEDATA:ten_tep.duoi]] nội dung tệp [[/FILEDATA]] để TẠO tệp văn bản/mã (txt, md, json, csv, py, js, html...) với đúng nội dung bạn viết bên trong (không bọc thêm ```); '
    + '[[IMG:https://...]] gửi ảnh, [[VIDEO:https://...]] gửi video, [[FILE:https://...|ten_tep.duoi]] gửi tệp từ một link https. '
    + 'Chỉ dùng link https THẬT mà bạn chắc chắn tồn tại, tuyệt đối không bịa link. Chỉ gửi tệp khi người dùng cần hoặc yêu cầu; hỏi đáp bình thường thì chỉ trả lời chữ. '
    + 'Tối đa ' + MAX_OUT_FILES + ' tệp mỗi lần. Không chèn dữ liệu riêng tư (ID, key, nội dung đoạn chat) vào link. Không giải thích về các thẻ này.';
  if (IMAGE_MODEL) r += ' Để TỰ VẼ một ảnh mới, dùng [[GENIMG:mô tả ảnh chi tiết bằng tiếng Anh]] (tối đa ' + MAX_GENIMG + ' ảnh).';
  return r;
}

// Chụp các tin gần đây của kênh thành văn bản cho AI (giờ Việt Nam, UTC+7)
function buildContext(n) {
  if (!n) return '';
  const now = Date.now();
  const list = (Array.isArray(ctx.recent) ? ctx.recent : [])
    .filter(m => !m.self && now - m.t < CTX_MAX_AGE && m.text && m.text.trim() !== '.')
    .slice(-n);
  return list.map(m => {
    const hhmm = new Date(m.t + 7 * 3600 * 1000).toISOString().slice(11, 16);
    const who = m.user + (m.bot ? ' [bot]' : '') + ' (ID: ' + m.userId + ')';
    return '[' + hhmm + '] ' + who + ': ' + String(m.text).replace(/\s+/g, ' ').slice(0, CTX_LINE_MAX);
  }).join('\n');
}

// ---------- TỆP ĐÍNH KÈM (người dùng -> AI) ----------
const extOf = n => ((String(n || '').match(/\.([a-z0-9]+)$/i) || [])[1] || '').toLowerCase();
function kindOf(a) {
  const ext = extOf(a.name), ct = String(a.contentType || '').toLowerCase();
  if (ct.startsWith('image/') || IMG_EXT.includes(ext)) return 'image';
  if (ct.startsWith('video/') || VID_EXT.includes(ext)) return 'video';
  if (ct.startsWith('audio/') || AUD_EXT.includes(ext)) return 'audio';
  if (ct.startsWith('text/') || /json|xml|javascript|yaml/.test(ct) || TXT_EXT.includes(ext)) return 'text';
  return 'other';
}
// Lấy tệp từ tin gọi bot; nếu không có thì lấy tệp chính người này vừa gửi ngay trước đó
function gatherAtts() {
  let list = Array.isArray(ctx.attachments) ? ctx.attachments : [];
  if (!list.length) {
    const now = Date.now();
    const prev = (Array.isArray(ctx.recent) ? ctx.recent : []).filter(m => m.userId === uid && !m.self && now - m.t < ATT_LOOKBACK && m.files && m.files.length).slice(-1)[0];
    if (prev) list = prev.files;
  }
  return list.filter(a => a && a.url).slice(0, MAX_ATTACH);
}

// ---------- TỆP AI GỬI LẠI (AI -> người dùng) ----------
function safeName(n) {
  n = String(n || 'file.txt').trim().replace(/[\\\/:*?"<>|\x00-\x1f]/g, '_').replace(/\s+/g, ' ').slice(-80);
  if (!n || n === '.' || n === '..') n = 'file.txt';
  const e = extOf(n);
  if (!e) n += '.txt'; else if (BAD_EXT.includes(e)) n += '.txt';
  return n;
}
function okUrl(u) {
  try {
    const x = new URL(u);
    if (x.protocol !== 'https:') return false;
    if (FILE_URL_ALLOW.length && !FILE_URL_ALLOW.some(h => x.hostname === h || x.hostname.endsWith('.' + h))) return false;
    return true;
  } catch (e) { return false; }
}
function nameFromUrl(u, kind) {
  let n = '';
  try { n = decodeURIComponent(new URL(u).pathname.split('/').pop() || ''); } catch (e) { /* bỏ qua */ }
  if (!/\.[a-z0-9]{2,5}$/i.test(n)) n = /^(IMG|IMAGE|ANH)$/i.test(kind) ? 'image.png' : /^VIDEO$/i.test(kind) ? 'video.mp4' : 'file.bin';
  return n;
}
const MIME_EXT = { png: 'png', jpeg: 'jpg', jpg: 'jpg', webp: 'webp', gif: 'gif', wav: 'wav', mpeg: 'mp3', mp3: 'mp3', ogg: 'ogg' };
let fileSeq = 0;
function fileFromData(dataUrl) {   // data:image/png;base64,xxxx  ->  { name, base64 }
  const m = String(dataUrl).match(/^data:([a-z]+)\/([a-z0-9.+-]+);base64,([A-Za-z0-9+\/=\s]+)$/i);
  if (!m) return null;
  return { name: (m[1].toLowerCase() === 'image' ? 'image' : m[1].toLowerCase()) + '-' + (++fileSeq) + '.' + (MIME_EXT[m[2].toLowerCase()] || 'bin'), base64: m[3].replace(/\s+/g, '') };
}
function fileFromAny(u, hint) {
  if (!u) return null;
  u = String(u);
  if (u.startsWith('data:')) return fileFromData(u);
  return okUrl(u) ? { name: safeName(nameFromUrl(u, hint || 'IMG')), url: u } : null;
}
// Tách các thẻ tệp khỏi câu trả lời của AI
function extractTags(s) {
  const files = [], gens = [];
  s = s.replace(/\[\[\s*FILEDATA\s*:\s*([^\]\n]{1,80}?)\s*\]\]\r?\n?([\s\S]*?)\[\[\s*\/\s*FILEDATA\s*\]\]/gi, (m, name, body) => {
    body = body.replace(/^\s*```[^\n]*\n/, '').replace(/\n?```\s*$/, '');
    files.push({ name: safeName(name), text: body.slice(0, MAX_OUT_FILE_TEXT) });
    return '';
  });
  s = s.replace(/\[\[\s*(IMG|IMAGE|ANH|VIDEO|FILE)\s*:\s*(https?:\/\/[^\s\]|]+)(?:\s*\|\s*([^\]]{1,80}))?\s*\]\]/gi, (m, k, url, name) => {
    if (okUrl(url)) files.push({ name: safeName(name || nameFromUrl(url, k)), url: url });
    return '';
  });
  s = s.replace(/\[\[\s*GENIMG\s*:\s*([^\]]{3,500})\]\]/gi, (m, p) => { gens.push(p.trim()); return ''; });
  s = s.replace(/!\[[^\]]*\]\((data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+\/=\s]+)\)/gi, (m, u) => { const f = fileFromData(u); if (f) files.push(f); return ''; });
  s = s.replace(/!\[[^\]]*\]\((https:\/\/[^\s)]+)\)/gi, (m, u) => { const f = fileFromAny(u, 'IMG'); if (f) files.push(f); return ''; });
  return { out: s.replace(/\n{3,}/g, '\n\n').trim(), files: files, gens: gens };
}

async function genImage(prompt) {
  const res = await fetch(IMAGE_API_URL, {
    method: 'POST',
    headers: { 'Authorization': 'Bearer ' + XKIRO_API_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: IMAGE_MODEL, prompt: prompt, n: 1 })
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  const d = await res.json();
  const it = (d.data || [])[0] || {};
  if (it.b64_json) return { name: 'image-' + (++fileSeq) + '.png', base64: it.b64_json };
  if (it.url && okUrl(it.url)) return { name: 'image-' + (++fileSeq) + '.png', url: it.url };
  throw new Error('API không trả ảnh');
}

// Gọi API chat (HTTP_TIMEOUT = 0 -> không giới hạn thời gian chờ)
async function callChat(messages) {
  const ac = new AbortController();
  const tm = HTTP_TIMEOUT > 0 ? setTimeout(() => ac.abort(), HTTP_TIMEOUT) : null;
  try {
    return await fetch(API_URL, {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + XKIRO_API_KEY, 'Content-Type': 'application/json' },
      signal: ac.signal,
      body: JSON.stringify({ model: model, messages: messages, max_tokens: MAX_TOKENS })
    });
  } finally { if (tm) clearTimeout(tm); }
}

// ================= LẦN 2: HẸN GIỜ -> GỌI API -> SỬA TIN "." =================
if (ctx.event === 'timer') {
  const jobId = String((ctx.timer && ctx.timer.data) || '');
  const job = store.jobs[jobId];
  if (!job) {
    store.busy = 0;
    if (jobId) ui.edit('ai' + jobId, '⚠️ Lượt trả lời này bị mất (bot vừa khởi động lại?), hỏi lại giúp mình nhé.');
    return;
  }
  delete store.jobs[jobId];

  let out = '', err = '', outFiles = [];
  const notes = [];
  try {
    store.hist = store.hist || {};
    const hist = store.hist[ctx.channelId] = store.hist[ctx.channelId] || [];
    // Ngữ cảnh kênh được đưa vào system prompt (không lưu vào trí nhớ để khỏi phình to)
    const sys = SYSTEM_PROMPT + punishRules(job.priv, job.uid) + fileRules(job.filesOk) + (job.context
      ? '\n\n=== Đoạn chat gần đây trong kênh (cũ -> mới, giờ VN) ===\n' + job.context + '\n=== Hết đoạn chat ==='
      : '');

    // ---- Đọc tệp văn bản & chuẩn bị ảnh / video / âm thanh người dùng gửi ----
    const textBlocks = [];
    let total = 0;
    for (const f of (job.texts || [])) {
      try {
        if (f.size && f.size > MAX_TEXT_BYTES) { textBlocks.push('[Tệp "' + f.name + '" quá lớn nên không đọc]'); continue; }
        if (total >= MAX_TEXT_TOTAL) { textBlocks.push('[Tệp "' + f.name + '" bị bỏ qua vì đã đủ dung lượng đọc]'); continue; }
        const r = await fetch(f.url);
        if (!r.ok) throw new Error('HTTP ' + r.status);
        let s = Buffer.from(await r.arrayBuffer()).toString('utf8');
        if (s.indexOf('\u0000') >= 0) { textBlocks.push('[Tệp "' + f.name + '" là tệp nhị phân, không đọc được]'); continue; }
        const room = Math.min(MAX_TEXT_CHARS, MAX_TEXT_TOTAL - total);
        const cut = s.length > room;
        s = s.slice(0, room).replace(/\[\[/g, '[ [');   // phá thẻ [[...]] trong nội dung tệp
        total += s.length;
        textBlocks.push('[Nội dung tệp "' + f.name + '"' + (cut ? ' - đã cắt bớt' : '') + ']\n' + s + '\n[Hết tệp "' + f.name + '"]');
      } catch (e) {
        print('Lỗi đọc tệp ' + f.name + ': ' + e.message);
        textBlocks.push('[Không đọc được tệp "' + f.name + '"]');
      }
    }
    const mediaParts = [];
    for (const a of (job.media || [])) {
      if (a.kind === 'image') mediaParts.push({ type: 'image_url', image_url: { url: a.url } });
      else if (a.kind === 'video') mediaParts.push({ type: 'video_url', video_url: { url: a.url } });
      else if (a.kind === 'audio') {
        try {
          if (a.size && a.size > MAX_AUDIO_BYTES) throw new Error('quá lớn');
          const fmt = extOf(a.name) === 'mp3' ? 'mp3' : 'wav';
          const r = await fetch(a.url);
          if (!r.ok) throw new Error('HTTP ' + r.status);
          const b = Buffer.from(await r.arrayBuffer());
          if (b.length > MAX_AUDIO_BYTES) throw new Error('quá lớn');
          mediaParts.push({ type: 'input_audio', input_audio: { data: b.toString('base64'), format: fmt } });
        } catch (e) { print('Lỗi đọc âm thanh ' + a.name + ': ' + e.message); notes.push('-# ⚠️ Không đọc được âm thanh ' + a.name); }
      }
    }
    const fullText = job.userLine + (textBlocks.length ? '\n\n' + textBlocks.join('\n\n') : '');
    const mk = withMedia => [{ role: 'system', content: sys }, ...hist,
      { role: 'user', content: (withMedia && mediaParts.length) ? [{ type: 'text', text: fullText }, ...mediaParts] : fullText }];

    try {
      let res = await callChat(mk(true));
      if (!res.ok && mediaParts.length && ![401, 402, 429].includes(res.status)) {
        print('xKiro lỗi HTTP ' + res.status + ' khi gửi kèm ảnh/video, thử lại không kèm: ' + (await res.text()).slice(0, 200));
        notes.push('-# ⚠️ Model/API không đọc được ảnh/video/âm thanh đính kèm nên mình chỉ trả lời dựa vào chữ.');
        res = await callChat(mk(false));
      }
      if (!res.ok) {
        print('xKiro lỗi HTTP ' + res.status + ': ' + (await res.text()).slice(0, 300));
        err = res.status === 401 ? '⚠️ API key sai.'
          : res.status === 402 ? '⚠️ API hết số dư.'
          : res.status === 429 ? 'ai ngu dốt đang chết não.'
          : '⚠️ API lỗi HTTP ' + res.status;
      } else {
        const data = await res.json();
        const m = (data.choices && data.choices[0] && data.choices[0].message) || {};
        if (Array.isArray(m.content)) {   // một số API trả nội dung dạng mảng các phần
          for (const p of m.content) {
            if (!p) continue;
            if (p.type === 'text' || p.text) out += String(p.text || '');
            else if (p.type === 'image_url') { const f = fileFromAny(p.image_url && p.image_url.url, 'IMG'); if (f) outFiles.push(f); }
          }
        } else out = String(m.content || '');
        if (Array.isArray(m.images)) {    // model omni có thể trả ảnh ở đây
          for (const im of m.images) { const f = fileFromAny((im && im.image_url && im.image_url.url) || (im && im.url), 'IMG'); if (f) outFiles.push(f); }
        }
        if (m.audio && m.audio.data) {
          outFiles.push({ name: 'audio-' + (++fileSeq) + '.' + (m.audio.format === 'mp3' ? 'mp3' : 'wav'), base64: String(m.audio.data) });
          if (!out.trim() && m.audio.transcript) out = String(m.audio.transcript);
        }
      }
    } catch (e) {
      print('Lỗi fetch: ' + e.message);
      err = e.name === 'AbortError' ? 'chết não rồi thử lại đi' : '⚠️ Không gọi được API.';
    }

    out = out.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

    // ---- Tách thẻ tệp [[IMG:..]] [[FILEDATA:..]] ... khỏi câu trả lời và KIỂM TRA QUYỀN ----
    if (!err) {
      const ex = extractTags(out);
      out = ex.out;
      outFiles = outFiles.concat(ex.files);
      if (!job.filesOk) {
        if (outFiles.length || ex.gens.length) notes.push('-# 🚫 Bạn chưa được cấp quyền nhận tệp / ảnh / video từ AI.');
        outFiles = [];
      } else {
        for (const gp of ex.gens.slice(0, MAX_GENIMG)) {
          if (!IMAGE_MODEL) { notes.push('-# ⚠️ Chưa bật tính năng tạo ảnh (IMAGE_MODEL trống).'); break; }
          try { outFiles.push(await genImage(gp)); }
          catch (e) { print('Lỗi tạo ảnh: ' + e.message); notes.push('-# ⚠️ Không tạo được ảnh: ' + e.message); }
        }
      }
    }
    outFiles = outFiles.slice(0, MAX_OUT_FILES);

    // ---- Tách thẻ phạt [[MUTE:3]] / [[TU:3]] / [[MUTE:3:ID]] khỏi câu trả lời và KIỂM TRA QUYỀN ----
    const punish = [];
    if (!err) {
      out = out.replace(/\[\[\s*(MUTE|TU|TÙ)\s*:\s*(\d{1,4})(?:\s*:\s*<?@?!?(\d{15,25})>?)?\s*\]\]/gi, (m, kind, sec, tid) => {
        punish.push({ kind: kind.toUpperCase().replace('TÙ', 'TU'), sec: clamp(sec, MUTE_MIN, MUTE_MAX), tid: tid || '' });
        return '';
      }).replace(/\s+$/g, '').trim();
    }
    const done = new Set();
    for (const p of punish) {
      if (done.size >= MAX_PUNISH) break;
      const target = p.tid || job.uid;
      let why = '';
      if (!target || target === BOT_ID) why = 'đối tượng không hợp lệ';
      else if (target !== job.uid && !job.priv) why = 'người gọi không có đặc quyền phạt người khác';
      else if (target !== job.uid && !(job.ids || []).includes(target)) why = 'ID không có trong tin nhắn của người ra lệnh';
      else if (PRIV_IDS.includes(target)) why = 'không được phạt người có đặc quyền';
      if (why) { print('Bỏ qua phạt ' + p.kind + ' ' + target + ': ' + why); continue; }
      if (done.has(target)) continue;
      done.add(target);
      mute(target, p.sec, 'AI ' + (p.kind === 'TU' ? 'tù' : 'mute') + ' ' + p.sec + 's (' + (target === job.uid ? 'khiêu khích bot' : 'theo lệnh ID ' + job.uid) + ')');
      print('AI ' + p.kind + ' ' + target + ' ' + p.sec + 's');
    }

    if (err && !out) out = err;
    else {
      if (!out && !outFiles.length) out = '...';
      hist.push({ role: 'user', content: job.userLine },
        { role: 'assistant', content: out + (outFiles.length ? ' [đã gửi tệp: ' + outFiles.map(f => f.name).join(', ') + ']' : '') });
      while (hist.length > MEMORY_TURNS * 2) hist.shift();
    }
  } catch (e) {
    print('Lỗi script: ' + ((e && e.stack) || e));
    out = out || '⚠️ Script gặp lỗi khi xử lý, xem tab Log.';
    outFiles = [];
  } finally {
    store.busy = 0; // mở khóa cho câu hỏi tiếp theo
  }

  if (job.blocked) notes.push('-# 🚫 Bạn chưa được cấp quyền gửi tệp cho AI nên mình bỏ qua phần đính kèm. ID của bạn: `' + job.uid + '`');
  if (notes.length) out = (out ? out + '\n' : '') + notes.join('\n');
  const chunks = out ? splitText(out, CHUNK_SIZE).slice(0, MAX_CHUNKS) : [];
  if (!chunks.length) chunks.push('');
  if (job.showTime) chunks[chunks.length - 1] += '\n-# ⏱️ trả lời sau ' + fmtMs(Date.now() - job.t);
  const payload = { content: chunks[0] };
  if (outFiles.length) payload.files = outFiles;
  ui.edit(job.tag, payload);                                    // sửa tin "." thành câu trả lời (kèm tệp nếu có) và dừng đồng hồ
  for (let i = 1; i < chunks.length; i++) ui.send(chunks[i]);   // dài thì gửi thêm tin nối tiếp
  return;
}

// ================= LỆNH ĐIỀU KHIỂN =================
const cmd = text.match(/^!ai(?:\s+(\S+))?(?:\s+([\s\S]+))?$/i);
if (cmd) {
  const sub = (cmd[1] || '').toLowerCase(), arg = (cmd[2] || '').trim();
  if (sub === 'id') {
    const target = idOf(arg);
    return target ? 'ID của người được nhắc: `' + target + '`' : 'ID của bạn: `' + uid + '`';
  }
  if (['on', 'bat', 'bật', 'off', 'tat', 'tắt', 'model', 'persona', 'clear', 'allow', 'deny', 'users', 'context', 'ngucanh',
    'file', 'tep', 'tệp', 'fileallow', 'filedeny', 'fileusers', 'time', 'dongho'].includes(sub) && !isStaff) return 'Chỉ Admin / chủ server mới dùng được.';
  if (['on', 'bat', 'bật'].includes(sub)) { store.enabled = true; return '✅ AI đã **BẬT**.'; }
  if (['off', 'tat', 'tắt'].includes(sub)) { store.enabled = false; return '⛔ AI đã **TẮT**.'; }
  if (sub === 'model') { if (!arg) return 'Model hiện tại: `' + model + '`'; store.model = arg; return 'Đã đổi model sang `' + arg + '`'; }
  if (sub === 'clear') { store.hist = {}; store.busy = 0; store.jobs = {}; return '🧹 Đã xóa trí nhớ.'; }
  if (sub === 'context' || sub === 'ngucanh') {
    if (!arg) return '👀 AI đang đọc **' + ctxN + '** tin gần nhất trong kênh (0 = tắt, tối đa ' + MAX_CTX_MSGS + '). Dùng: `!ai context <số>`';
    const n = parseInt(arg, 10);
    if (isNaN(n) || n < 0 || n > MAX_CTX_MSGS) return 'Nhập số từ 0 đến ' + MAX_CTX_MSGS + '.';
    store.ctxN = n;
    return n ? '👀 AI sẽ đọc **' + n + '** tin gần nhất trong kênh khi bị tag.' : '👀 Đã tắt đọc ngữ cảnh kênh.';
  }
  if (sub === 'allow') {
    const t = idOf(arg); if (!t) return 'Dùng: `!ai allow <id hoặc @user>`';
    if (!store.allow.includes(t)) store.allow.push(t);
    return '✅ Đã cho phép `' + t + '`. Danh sách hiện có ' + store.allow.length + ' người.';
  }
  if (sub === 'deny') {
    const t = idOf(arg); if (!t) return 'Dùng: `!ai deny <id hoặc @user>`';
    store.allow = store.allow.filter(x => x !== t);
    return '🚫 Đã bỏ `' + t + '` khỏi danh sách.' + (store.allow.length ? '' : ' Danh sách trống nên ai cũng dùng được.');
  }
  if (sub === 'users') return store.allow.length ? 'Được phép: ' + store.allow.map(x => '`' + x + '`').join(', ') + ' (Admin luôn được dùng)' : 'Danh sách trống: ai cũng dùng được.';
  // ----- MỚI: quản lý ảnh / video / tệp -----
  if (sub === 'file' || sub === 'tep' || sub === 'tệp') {
    const a = arg.toLowerCase();
    if (['on', 'bat', 'bật'].includes(a)) { store.fileOn = true; return '📎 Ảnh / video / tệp đã **BẬT**.'; }
    if (['off', 'tat', 'tắt'].includes(a)) { store.fileOn = false; return '📎 Ảnh / video / tệp đã **TẮT**.'; }
    return '📎 Ảnh / video / tệp: **' + (filesOn ? 'BẬT' : 'TẮT') + '** | ' + (store.fileAllow.length ? 'chỉ cho ' + store.fileAllow.length + ' người trong danh sách (Admin luôn được)' : 'mọi người được dùng AI đều dùng được')
      + '. Dùng: `!ai file on|off`, `!ai fileallow <id>`, `!ai filedeny <id>`, `!ai fileusers`';
  }
  if (sub === 'fileallow') {
    const t = idOf(arg); if (!t) return 'Dùng: `!ai fileallow <id hoặc @user>`';
    if (!store.fileAllow.includes(t)) store.fileAllow.push(t);
    return '📎 Đã cho `' + t + '` gửi/nhận tệp với AI. Từ giờ **chỉ** ' + store.fileAllow.length + ' người trong danh sách (và Admin) dùng được tệp.';
  }
  if (sub === 'filedeny') {
    const t = idOf(arg); if (!t) return 'Dùng: `!ai filedeny <id hoặc @user>`';
    store.fileAllow = store.fileAllow.filter(x => x !== t);
    return '🚫 Đã bỏ `' + t + '` khỏi danh sách tệp.' + (store.fileAllow.length ? '' : ' Danh sách trống nên ai dùng được AI cũng dùng được tệp.');
  }
  if (sub === 'fileusers') return store.fileAllow.length ? 'Được dùng tệp: ' + store.fileAllow.map(x => '`' + x + '`').join(', ') + ' (Admin luôn được dùng)' : 'Danh sách trống: ai dùng được AI cũng dùng được tệp.';
  if (sub === 'time' || sub === 'dongho') {
    const a = arg.toLowerCase();
    if (['on', 'bat', 'bật'].includes(a)) { store.showTime = true; return '⏱️ Đã **BẬT** dòng "trả lời sau X giây".'; }
    if (['off', 'tat', 'tắt'].includes(a)) { store.showTime = false; return '⏱️ Đã **TẮT** dòng "trả lời sau X giây" (đồng hồ đếm lúc chờ vẫn chạy).'; }
    return '⏱️ Dòng thời gian trả lời: **' + (showTime ? 'BẬT' : 'TẮT') + '**. Dùng: `!ai time on|off`';
  }
  if (sub === 'persona') {
    if (!arg) return '🎭 Tính cách hiện tại: ' + persona + '\nMẫu có sẵn: ' + Object.keys(PRESETS).map(k => '`' + k + '`').join(', ') + '\nDùng: `!ai persona <mẫu | văn bản tự viết | reset>`';
    if (arg.toLowerCase() === 'reset') { store.persona = ''; store.hist = {}; return '🎭 Đã về tính cách mặc định.'; }
    store.persona = PRESETS[arg.toLowerCase()] || arg.slice(0, MAX_PERSONA);
    store.hist = {};
    return '🎭 Đã đổi tính cách: ' + store.persona;
  }
  return 'AI đang **' + (store.enabled === false ? 'TẮT' : 'BẬT') + '** | model: `' + model + '` | đọc ' + ctxN + ' tin kênh | tệp: ' + (filesOn ? 'BẬT' : 'TẮT') + (store.busy && Date.now() - store.busy < LOCK_TTL ? ' | đang xử lý 1 câu' : '');
}

// ================= LẦN 1: BỊ TAG -> GỬI TIN "." + HẸN GIỜ =================
if (!/^\d{15,25}$/.test(BOT_ID)) { print('Chưa điền BOT_ID.'); return; }
const tagged = text.includes('<@' + BOT_ID + '>') || text.includes('<@!' + BOT_ID + '>') || (ctx.mentions || []).some(m => m.id === BOT_ID);
if (!tagged) return;
if (store.enabled === false) return;
if (!XKIRO_API_KEY || XKIRO_API_KEY.includes('DIEN_KEY')) return 'Chưa điền XKIRO_API_KEY.';

// Kiểm tra ID người dùng
if (store.allow.length && !isStaff && !store.allow.includes(uid)) return '🚫 Bạn chưa được cấp quyền dùng AI. ID của bạn: `' + uid + '`';

// Chỉ 1 tiến trình một lúc (khóa giữ từ lần 1 đến hết lần 2)
if (store.busy && Date.now() - store.busy < LOCK_TTL) return '⏳ Bot đang trả lời câu khác, đợi chút rồi hỏi lại nhé.';

// Quyền dùng ảnh / video / tệp do CODE quyết định (Admin luôn được; danh sách trống = mọi người)
const filesOk = filesOn && (isStaff || !store.fileAllow.length || store.fileAllow.includes(uid));
const atts = filesOk ? gatherAtts() : [];
const blocked = !filesOk && Array.isArray(ctx.attachments) && ctx.attachments.length > 0;   // có gửi tệp nhưng không có quyền
const media = [], texts = [];
for (const a of atts) {
  const k = kindOf(a);
  if (k === 'image' || k === 'video' || k === 'audio') media.push({ kind: k, url: a.url, name: String(a.name || 'file'), size: a.size || 0 });
  else if (k === 'text') texts.push({ name: String(a.name || 'file.txt'), url: a.url, size: a.size || 0 });
}
const attLine = atts.length
  ? ' [Đính kèm: ' + atts.map(a => String(a.name || 'file') + ' (' + ({ image: 'ảnh', video: 'video', audio: 'âm thanh', text: 'văn bản', other: 'loại không đọc được' }[kindOf(a)]) + ')').join(', ') + ']'
  : '';

// Bỏ mọi thẻ [[...]] người dùng gõ, tránh họ tự chèn thẻ phạt / thẻ tệp cho AI chép lại
let q = text.replace(/<@!?\d{15,25}>/g, ' ').replace(/\[\[[^\]]*\]\]/g, ' ').replace(/\s+/g, ' ').trim();
if (!q) q = atts.length ? '(không ghi gì, chỉ gửi tệp đính kèm - hãy xem và nhận xét/xử lý chúng)' : '(chỉ gọi tên, không nói gì)';

// dọn job cũ bị bỏ dở (bot khởi động lại...)
for (const k of Object.keys(store.jobs)) if (Date.now() - store.jobs[k].t > 300000) delete store.jobs[k];

// Quyền phạt người khác do CODE quyết định dựa trên ID Discord thật (ctx.user.id), không phải tên hiển thị
const isPriv = PRIV_IDS.includes(uid);
const ids = Array.from(new Set((text.match(/\d{15,25}/g) || []).concat((ctx.mentions || []).map(m => m.id))))
  .filter(x => x !== BOT_ID && x !== uid);

const jobId = String(Date.now()) + String(Math.floor(Math.random() * 1000));
const tag = 'ai' + jobId;
store.busy = Date.now();
store.jobs[jobId] = {
  tag: tag,
  t: Date.now(),
  uid: uid,
  priv: isPriv,
  ids: isPriv ? ids : [],
  filesOk: filesOk,
  blocked: blocked,
  showTime: showTime,
  media: media,
  texts: texts,
  context: buildContext(ctxN).replace(/\[\[[^\]]*\]\]/g, ' '),   // chụp đoạn chat ngay lúc bị tag (lần hẹn giờ không có tin gốc); bỏ thẻ [[...]] do người khác gõ
  userLine: ctx.user.display + ' (ID: ' + uid + (isStaff ? ', Admin' : '') + '): ' + q.slice(0, 1500) + attLine
    + (isPriv && ids.length ? ' [ID được nhắc: ' + ids.join(', ') + ']' : '')
};

// Tin "đang trả lời" hiện ngay khi script kết thúc, TỰ ĐẾM GIÂY (cần index.js bản vá v2; bản cũ chỉ hiện "0s" đứng yên)
const loadTpl = LOADING + ' chết não trong ... ⏱️ {s}';
ui.send({ content: loadTpl.replace('{s}', '0s'), counter: loadTpl }, tag);
ui.after(1, jobId);     // 1 giây sau chạy lại script (ctx.event === 'timer') để gọi API và sửa tin
return;

